"""Prepare OpenDriver for an episode.

OpenDriver keeps its state in a JSON database inside the guest rather than
behind a loopback endpoint.  Preparation reads that database and confirms the
episode starts signed out with the accounts the instruction signs in as, and
that no login session is already open.  It signs nobody in, takes no ride, opens
no ticket and requests no payout.
"""

from __future__ import annotations

from typing import Any, Mapping

from evaluators.cua_review.core.initialization import InitializationError, MacAppInitializer

#: OpenDriver's durable database, relative to the guest home directory.
DEFAULT_DB_PATH = (
    "~/Library/Application Support/OS-Omni Open Apps/opendriver/"
    "src/shared/backend/data/opendriver-db.json"
)


class OpenDriverInitializer(MacAppInitializer):
    """Confirm the signed-out OpenDriver starting point an episode assumes."""

    INITIALIZER_ID = "initializers.macos.opendriver:OpenDriverInitializer"
    APP_NAME = "OpenDriver"
    BUNDLE_ID = "local.osomni.opendriver"
    SETTLE_MS = 2000

    def verify_preconditions(self, controller: Any, params: Mapping[str, Any]) -> str:
        db_path = str(params.get("db_path") or DEFAULT_DB_PATH)
        script = "\n".join(
            [
                "import json",
                "from pathlib import Path",
                f"path = Path({db_path!r}).expanduser()",
                "if not path.is_file():",
                "    print(json.dumps({'exists': False, 'path': str(path)}))",
                "else:",
                "    database = json.loads(path.read_text(encoding='utf-8'))",
                "    print(json.dumps({'exists': True, 'path': str(path), 'database': database}, ensure_ascii=False))",
            ]
        )
        evidence = self._guest_json(controller, script, what="the OpenDriver database")
        if not evidence.get("exists"):
            raise InitializationError(
                f"the OpenDriver database is missing at {evidence.get('path')}"
            )
        database = evidence.get("database") or {}

        users = database.get("users") or []
        emails = {
            str(user.get("email") or "").casefold()
            for user in users
            if isinstance(user, Mapping)
        }
        expected = [str(email) for email in (params.get("expected_users") or [])]
        missing = [email for email in expected if email.casefold() not in emails]
        if missing:
            raise InitializationError(
                "the OpenDriver database does not carry the seeded account(s) "
                + ", ".join(missing)
            )

        sessions = database.get("sessions") or []
        if sessions:
            raise InitializationError(
                f"OpenDriver already carries {len(sessions)} open session(s) before the task ran"
            )

        return (
            f"the OpenDriver database carries {len(users)} users including "
            + ", ".join(expected)
            + ", with no open session"
        )
